<?php
/** TEMP PS S1611 run e15d — D: deploy darbalaukis v3.10.6 (lipdukai privalomi klientui); T (naujas procesas): 1) likutis seka kelią (18593 _own_stock_qty, 19708 _stock) 2) Dropshipping kortelė be „Užsakyti be lipdukų“ 3) „VF išsiuntė“ be numerio — neleidžia */
add_filter('pre_wp_mail', function($r,$a){ $l=(array)get_option('ps_e15_mail',array()); $l[]=array('kam'=>is_array($a['to'])?implode(',',$a['to']):$a['to'],'tema'=>$a['subject']); update_option('ps_e15_mail',array_slice($l,-12),false); return true; },4,2);
add_action('init', function(){
  if (!isset($_GET['ps_e15d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e15d'])); $o=array('v'=>'run e15d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $c3='';
    $p1=@file_get_contents($bk.'/dl-v3106.part1'); $p2=@file_get_contents($bk.'/dl-v3106.part2'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen($c3));
    $code=base64_decode($p1.$p2.$c3,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='770feb233b28fefb8a52968b6a290dd0') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='786445f11fbe62a677bf26d23b3baf62') { $o['STOP']='gyvas ne v3.10.5 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3105-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v3106.part1'); @unlink($bk.'/dl-v3106.part2');
  }
  if($f==='T'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); update_option('ps_e15_mail',array(),false);
    $u=get_user_by('login','testuotojas'); $uid=$u?$u->ID:1; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp); $lc=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$lc)));
    $_COOKIE[LOGGED_IN_COOKIE]=$lc; wp_set_current_user($uid);
    $PAR=admin_url('admin.php?page=ps-desk&eile=paruosta');
    $REQ=function($url,$post=null) use($cs){ $a=array('cookies'=>$cs,'timeout'=>120,'sslverify'=>false,'redirection'=>0); $r=$post!==null?wp_remote_post($url,array_merge($a,array('body'=>$post))):wp_remote_get($url,$a); if(is_wp_error($r)) return array('err'=>$r->get_error_message()); $loc=wp_remote_retrieve_header($r,'location'); if($loc){ parse_str((string)parse_url($loc,PHP_URL_QUERY),$q); return isset($q['pd_nr'])?rawurldecode($q['pd_nr']):($q['pd_ok']??wp_remote_retrieve_response_code($r)); } return array('code'=>wp_remote_retrieve_response_code($r),'body'=>wp_remote_retrieve_body($r)); };
    $dl=function($v,$id,$extra=array()) use($REQ,$PAR){ return $REQ(admin_url('admin-post.php').'?'.http_build_query(array_merge(array('action'=>'ps_dl_veiksmas','v'=>$v,'id'=>$id,'_wpnonce'=>wp_create_nonce('ps_dl_'.$v.'_'.$id),'g'=>$PAR),$extra))); };
    $lik=function() { clean_post_cache(18593); clean_post_cache(19708); wp_cache_flush(); return array('18593_own'=>get_post_meta(18593,'_own_stock_qty',true),'18593_stock'=>get_post_meta(18593,'_stock',true),'19708_stock'=>get_post_meta(19708,'_stock',true),'19708_own'=>get_post_meta(19708,'_own_stock_qty',true)); };
    $eil=function($id){ wp_cache_flush(); $ord=wc_get_order($id); $r=new ReflectionMethod('Petshop_Darbalaukis','faktai'); $r->setAccessible(true); $fx=$r->invoke(null,$ord,array()); $e=array(); foreach($fx['eil'] as $iid=>$l){ $it=$ord->get_item($iid); $e[$iid]=$l['q'].'x '.mb_substr($l['n'],0,18).' ['.$l['k'].'/'.$l['src'].'] av_qty='.json_encode($l['av_qty']).' galimi='.implode(',',array_keys(array_filter($l['galimi']))).' reduced='.$it->get_meta('_ps_av_reduced_qty').'/'.$it->get_meta('_ps_av_reduced'); } return array('st'=>$ord->get_status(),'eiles'=>$fx['eiles'],'eil'=>$e,'av_reduced'=>$ord->get_meta('_ps_av_reduced'),'restored'=>$ord->get_meta('_ps_av_restored')); };
    $naujas=function($pids) { $ord=wc_create_order(array('customer_id'=>5787,'created_via'=>'checkout')); $adr=array('first_name'=>'Testas','last_name'=>'Klientas','email'=>'s1609.klientas@avesa.lt','phone'=>'+37060000000','address_1'=>'Testų g. 33','city'=>'Vilnius','postcode'=>'01100','country'=>'LT'); $ord->set_address($adr,'billing'); unset($adr['email'],$adr['phone']); $ord->set_address($adr,'shipping'); foreach($pids as $pid){ $ord->add_product(wc_get_product($pid),1); } $sh=new WC_Order_Item_Shipping(); $sh->set_method_id('shopup_venipak_shipping_courier_method'); $sh->set_instance_id(2); $sh->set_method_title('VENIPAK Kurjeris'); $sh->set_total(3.49); $ord->add_item($sh); $ord->set_payment_method('bacs'); $ord->set_payment_method_title('Banko pavedimas'); $ord->calculate_totals(); $ord->save(); return $ord; };
    // 1) LIKUTIS SEKA KELIĄ
    $o['L0_pries']=$lik(); $ord=$naujas(array(18593,19708)); $A=$ord->get_id(); $o['A']=$A; $ord->payment_complete('AUDITAS-T36');
    $o['L1_po_apmok']=array('lik'=>$lik(),'eil'=>$eil($A));
    $ord=wc_get_order($A); $iids=array(); foreach($ord->get_items() as $iid=>$it){ $iids[(int)$it->get_product_id()]=$iid; }
    $o['L2_kelias_18593_tiesiai']=$dl('kelias',$A,array('iid'=>$iids[18593],'k'=>'tiesiai')); $o['L2_po']=array('lik'=>$lik(),'eil'=>$eil($A));
    $o['L3_kelias_18593_av']=$dl('kelias',$A,array('iid'=>$iids[18593],'k'=>'av')); $o['L3_po']=array('lik'=>$lik(),'eil'=>$eil($A));
    $o['L4_kelias_19708_tiesiai']=$dl('kelias',$A,array('iid'=>$iids[19708],'k'=>'tiesiai')); $o['L4_po']=array('lik'=>$lik(),'eil'=>$eil($A));
    $ord=wc_get_order($A); $ord->update_status('cancelled','S1611 testas (likutis seka kelią) — atšaukta'); $o['L5_atsaukus']=array('lik'=>$lik(),'eil'=>$eil($A),'notes'=>array_map(function($n){return mb_substr($n->content,0,220);},wc_get_order_notes(array('order_id'=>$A,'limit'=>6))));
    // 2)+3) LIPDUKAI PRIVALOMI: mišrus VF+Prins → Dropshipping kortelėje mygtuko „be lipdukų“ nėra; per variklį be lipdukų → „VF išsiuntė“ neleidžia
    $prins=0; foreach(wc_get_order(35421)->get_items() as $it){ if('prins'===(string)$it->get_meta('_ps_source')){ $prins=(int)$it->get_product_id(); break; } }
    $ord=$naujas(array(35357,$prins)); $B=$ord->get_id(); $o['B']=$B; $ord->payment_complete('AUDITAS-T37'); $ord=wc_get_order($B);
    foreach($ord->get_items() as $iid=>$it){ $s=(string)$it->get_meta('_ps_source'); if($s&&$s!=='av'){ $dl('kelias',$B,array('iid'=>$iid,'k'=>'tiesiai')); } } $o['B_rusiuoti']=$dl('rusiuoti',$B);
    $ds=$REQ(admin_url('admin.php?page=ps-desk&eile=laiskai')); $b=is_array($ds)?($ds['body']??''):''; $o['B_dropshipping_kortele']=array('code'=>$ds['code']??null,'be_lipduku_mygtukas'=>strpos($b,'be_lipduku')!==false,'be_lipduku_tekstas'=>stripos($b,'be lipdukų')!==false,'uzsakyti_is_VF'=>strpos($b,'Užsakyti iš VF')!==false,'lipdukai_n'=>preg_match('/Lipdukai \((\d+)\)/',$b,$m)?$m[1]:null,'disabled_pirma_lipdukai'=>substr_count($b,'pirma lipdukai'));
    $o['B_vf_be_lipduku_variklis']=$REQ(admin_url('admin-post.php'),array('action'=>'ps_dropship_send','tiekejas'=>'vf','uzsakymai'=>$B,'_wpnonce'=>wp_create_nonce('ps_dropship_send'),'ps_dl_g'=>$PAR,'laisk_zyme'=>1,'be_lipduku'=>1,'laisk_man'=>1));
    $o['B_po_uzsakymo']=$eil($B);
    $o['B_vf_issiunte']=$dl('issiusta',$B,array('dalis'=>'vf','sekimo'=>1)); $o['B_po_issiusta']=$eil($B); $o['B_dalys_issiusta']=wc_get_order($B)->get_meta('_ps_dalys_issiusta');
    $o['B_visos']=$dl('issiusta',$B,array('sekimo'=>1));
    wc_get_order($B)->update_status('cancelled','S1611 testas (lipdukai privalomi) — atšaukta'); $o['B_st']=wc_get_order($B)->get_status();
    $o['mail']=array_map(function($m){return $m['kam'].' | '.$m['tema'];},(array)get_option('ps_e15_mail',array())); delete_option('ps_e15_mail');
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
});
